fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    let mut result = Vec::with_capacity(s.len());
    for i in 1..=s.len() {
        // Take the first `i` chars and collect them into a new Vec<char>
        result.push(s[..i].to_vec());
    }
    result
}

